 1	// Shared window-position helpers. Both the engine (tick loop) and the physics
 2	// module (throw/fall) need to read and write the pet window's logical position;
 3	// centralizing it keeps the DPI conversion in one place and avoids two copies
 4	// of the same `outerPosition / scaleFactor` dance drifting apart.
 5	
 6	import { getCurrentWindow } from "@tauri-apps/api/window";
 7	import { LogicalPosition } from "@tauri-apps/api/dpi";
 8	import type { Point } from "./types";
 9	
10	const win = getCurrentWindow();
11	
12	let cachedLogicalPos: Point | null = null;
13	let cachedScaleFactor: number | null = null;
14	let pendingPositionRead: Promise<Point | null> | null = null;
15	let trackingStarted = false;
16	
17	function copyPoint(pos: Point): Point {
18	  return { x: pos.x, y: pos.y };
19	}
20	
21	function startPositionTracking(): void {
22	  if (trackingStarted) return;
23	  trackingStarted = true;
24	  void win.onMoved(({ payload }) => {
25	    if (!cachedScaleFactor) {
26	      cachedLogicalPos = null;
27	      return;
28	    }
29	    cachedLogicalPos = { x: payload.x / cachedScaleFactor, y: payload.y / cachedScaleFactor };
30	  });
31	  void win.onScaleChanged(({ payload }) => {
32	    cachedScaleFactor = payload.scaleFactor;
33	    cachedLogicalPos = null;
34	  });
35	}
36	
37	/// Current window position in LOGICAL pixels (DPI-divided). Returns null if the
38	/// window or scaleFactor can't be read (e.g. window closing).
39	export async function currentLogicalPos(): Promise<Point | null> {
40	  startPositionTracking();
41	  if (cachedLogicalPos) return copyPoint(cachedLogicalPos);
42	  if (!pendingPositionRead) {
43	    pendingPositionRead = (async () => {
44	      try {
45	        const sf = await win.scaleFactor();
46	        const p = await win.outerPosition();
47	        cachedScaleFactor = sf;
48	        cachedLogicalPos = { x: p.x / sf, y: p.y / sf };
49	        return copyPoint(cachedLogicalPos);
50	      } catch {
51	        return null;
52	      } finally {
53	        pendingPositionRead = null;
54	      }
55	    })();
56	  }
57	  const pos = await pendingPositionRead;
58	  return pos ? copyPoint(pos) : null;
59	}
60	
61	/// Move the window to a logical-pixel position. Caller is responsible for
62	/// clamping to the work area first.
63	export async function setLogical(pos: Point): Promise<void> {
64	  await win.setPosition(new LogicalPosition(pos.x, pos.y));
65	  cachedLogicalPos = copyPoint(pos);
66	}
