   604	            // Background loop: make each persistent overlay click-through
   605	            // outside its opaque rectangle and persist every instance position.
   606	            let handle = app.handle().clone();
   607	            std::thread::spawn(move || {
   608	                let mut last_ignore: std::collections::HashMap<String, bool> = std::collections::HashMap::new();
   609	                let mut flip_logs: u32 = 0;
   610	                let mut last_saved = read_pet_positions();
   611	                let mut tick: u32 = 0;
   612	                loop {
   613	                    // 60ms (≈16Hz): click-through detection doesn't need 33Hz
   614	                    // polling. The cursor rarely traverses a pet's opaque rect
   615	                    // in <60ms, and halving the tick rate halves the Win32
   616	                    // GetCursorPos + GetWindowRect calls per second.
   617	                    std::thread::sleep(Duration::from_millis(60));
   618	
   619	                    // Snapshot all pet windows once per tick so spawns/closes
   620	                    // during the loop don't corrupt the iterator.
   621	                    let wins: Vec<(String, tauri::WebviewWindow)> = handle
   622	                        .webview_windows()
   623	                        .into_iter()
   624	                        .filter(|(label, _)| is_pet_window(label))
   625	                        .collect();
   626	                    // `is_visible` is the documented Tauri window getter. Keep
   627	                    // the fail-safe path on visibility lookup errors, but skip
   628	                    // all cursor and geometry work for known-hidden overlays.
   629	                    let visible_wins: Vec<_> = wins
   630	                        .iter()
   631	                        .filter(|(_, window)| window.is_visible().unwrap_or(true))
   632	                        .collect();
   633	                    let cur = if visible_wins.is_empty() {
   634	                        None
   635	                    } else {
   636	                        handle.cursor_position().ok()
   637	                    };
   638	
   639	                    // Snapshot all hit rects in ONE lock acquisition (instead of
   640	                    // N locks per tick). The clone is ~12 entries × 32 bytes.
   641	                    let rects: HitRectMap = handle
   642	                        .try_state::<Mutex<HitRectMap>>()
   643	                        .and_then(|s| s.lock().ok().map(|m| m.clone()))
   644	                        .unwrap_or_default();
   645	
   646	                    for (label, win) in &visible_wins {
   647	                        let Ok(wp) = win.outer_position() else { continue };
   648	                        // Fail-safe: no rect yet (webview still booting) or
   649	                        // cursor unreadable → keep INTERACTIVE.
   650	                        let inside = match &cur {
   651	                            Some(cur) => match rects.get(label) {
   652	                                Some(r) if r.w > 0.0 => {
   653	                                    let rx = cur.x - wp.x as f64;
   654	                                    let ry = cur.y - wp.y as f64;
   655	                                    rx >= r.x && rx <= r.x + r.w && ry >= r.y && ry <= r.y + r.h
   656	                                }
   657	                                _ => true, // no rect yet → stay interactive
   658	                            },
   659	                            None => true,
   660	                        };
   661	                        // ignore_cursor_events = true → clicks pass through.
   662	                        let ignore = !inside;
   663	                        if last_ignore.get(label) != Some(&ignore) {
   664	                            let _ = win.set_ignore_cursor_events(ignore);
   665	                            last_ignore.insert(label.clone(), ignore);
   666	                            if flip_logs < 60 {
   667	                                flip_logs += 1;
   668	                                let cur_str = cur.as_ref().map_or("err".to_string(), |c| format!("({:.0},{:.0})", c.x, c.y));
   669	                                dlog(&format!(
   670	                                    "hit flip: label={label} ignore={ignore} cur={cur_str} win=({},{})",
   671	                                    wp.x, wp.y
   672	                                ));
   673	                            }
   674	                        }
   675	                    }
   676	
   677	                    // Prune closed windows and persist every instance position,
   678	                    // both throttled to roughly once per second.
   679	                    tick = tick.wrapping_add(1);
   680	                    if tick % 17 == 0 {
   681	                        let active: std::collections::HashSet<&String> =
   682	                            wins.iter().map(|(label, _)| label).collect();
   683	                        if let Some(state) = handle.try_state::<Mutex<HitRectMap>>() {
   684	                            if let Ok(mut rects) = state.lock() {
   685	                                rects.retain(|label, _| active.contains(label));
   686	                            }
   687	                        }
   688	                        last_ignore.retain(|label, _| active.contains(label));
   689	
   690	                        let mut changed = false;
   691	                        for (label, window) in &wins {
   692	                            let Some(id) = label.strip_prefix(PET_WINDOW_PREFIX) else { continue };
   693	                            let Ok(position) = window.outer_position() else { continue };
   694	                            let next = (position.x, position.y);
   695	                            if last_saved.get(id) != Some(&next) {
   696	                                last_saved.insert(id.to_owned(), next);
   697	                                changed = true;
   698	                            }
   699	                        }
   700	                        if changed {
   701	                            if let Some(state) = handle.try_state::<Mutex<PetPositionMap>>() {
   702	                                if let Ok(mut positions) = state.lock() {
   703	                                    *positions = last_saved.clone();
   704	                                    write_pet_positions(&positions);
   705	                                }
